# Draws simple landmark silhouettes into questions/img/lm-*.svg (300x200, drawn by hand, no outside images).
# Left out on purpose: places of worship, holy sites (those belong to the Islamic edition) and statues of people or animals.
import os, math
OUT = os.path.join(os.path.dirname(__file__), '..', 'questions', 'img')
S = '#26304a'  # silhouette colour

def P(pts, c=S): return f'<polygon points="{" ".join(f"{x:.1f},{y:.1f}" for x, y in pts)}" fill="{c}"/>'
def R(x, y, w, h, c=S): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{c}"/>'
def Cc(cx, cy, r, c=S): return f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="{c}"/>'
def path(d, c=S, extra=''): return f'<path d="{d}" fill="{c}" {extra}/>'
def line(d, w, c=S): return f'<path d="{d}" fill="none" stroke="{c}" stroke-width="{w}" stroke-linecap="round"/>'
def ground(y=180, c='#5b6b4a'): return R(0, y, 300, 200 - y, c)
def water(y=170): return R(0, y, 300, 200 - y, '#3d6f9e') + line(f'M20,{y+10} h40 M120,{y+18} h50 M220,{y+9} h45', 2, '#8fb6d9')
def sand(y=170): return R(0, y, 300, 200 - y, '#e2c38b')

L = {}
L['eiffel'] = ground() + P([(146, 18), (154, 18), (160, 70), (172, 112), (196, 180), (172, 180), (160, 150), (140, 150), (128, 180), (104, 180), (128, 112), (140, 70)]) + \
    path('M138,180 Q150,152 162,180Z', '#cfe8f7') + R(124, 108, 52, 6) + R(136, 68, 28, 5) + R(148, 6, 4, 14)
L['pyramids'] = sand() + P([(30, 170), (105, 70), (180, 170)]) + P([(130, 170), (195, 85), (260, 170)], '#3a4664') + P([(230, 170), (260, 130), (290, 170)]) + \
    P([(105, 70), (180, 170), (150, 170)], '#3a4664')
L['pisa'] = ground() + f'<g transform="rotate(5 150 180)">' + R(126, 40, 48, 140) + ''.join(R(126, y, 48, 2, '#cfe8f7') for y in range(60, 180, 20)) + \
    ''.join(R(x, y + 5, 3, 11, '#cfe8f7') for y in range(60, 170, 20) for x in range(132, 172, 8)) + R(132, 26, 36, 14) + '</g>'
L['big-ben'] = ground() + R(132, 60, 36, 120) + R(128, 56, 44, 44) + Cc(150, 78, 15, '#f4e6b8') + line('M150,78 V68 M150,78 h8', 2) + \
    P([(128, 56), (150, 18), (172, 56)]) + R(148, 6, 4, 14) + R(60, 120, 72, 60) + R(168, 120, 90, 60) + ''.join(R(x, 112, 4, 10) for x in range(64, 130, 10)) + \
    ''.join(R(x, 112, 4, 10) for x in range(172, 256, 10))
L['colosseum'] = ground() + path('M30,180 V80 Q150,50 270,80 V140 Q240,150 230,180Z') + \
    ''.join(path(f'M{x},{y + 22} v-12 a6,6 0 0 1 12,0 v12z', '#cfe8f7') for y in (82, 112, 142) for x in range(40, 230 if y > 100 else 262, 22))
L['sydney-opera'] = water(160) + R(40, 150, 230, 12, '#d9cfb8') + ''.join(path(f'M{x},{150} Q{x + 6},{150 - h} {x + w},{150 - h * 1.05} Q{x + w * 0.7},{150 - h * 0.4} {x + w * 0.9},150Z', '#f4f1ea', 'stroke="#9aa3b5" stroke-width="2"')
    for x, w, h in [(60, 50, 70), (95, 45, 85), (130, 40, 60), (170, 45, 62), (200, 40, 76), (230, 30, 50)])
L['golden-gate'] = water(160) + R(70, 30, 12, 140, '#c0362c') + R(218, 30, 12, 140, '#c0362c') + R(70, 60, 12, 4, '#cfe8f7') + R(218, 60, 12, 4, '#cfe8f7') + \
    R(0, 128, 300, 8, '#c0362c') + line('M0,70 Q38,124 76,32 Q150,130 224,32 Q262,124 300,70', 3, '#c0362c') + \
    ''.join(line(f'M{x},{128} V{y}', 1, '#c0362c') for x, y in [(20, 92), (40, 108), (110, 82), (130, 100), (150, 104), (170, 100), (190, 82), (260, 108), (280, 92)])
L['tower-bridge'] = water(160) + ''.join(R(x, 50, 34, 120) + P([(x - 2, 50), (x + 17, 18), (x + 36, 50)]) + R(x - 4, 50, 6, 18) + R(x + 32, 50, 6, 18) + R(x + 12, 80, 10, 20, '#cfe8f7') for x in (80, 186)) + \
    R(114, 56, 72, 7) + R(114, 66, 72, 3) + R(0, 128, 80, 6) + R(220, 128, 80, 6) + R(114, 128, 72, 6) + \
    line('M0,100 Q40,140 80,60 M220,60 Q260,140 300,100', 3)
L['burj-khalifa'] = sand() + P([(146, 4), (154, 4), (156, 40), (160, 60), (164, 90), (170, 120), (178, 150), (186, 170), (114, 170), (122, 150), (130, 120), (136, 90), (140, 60), (144, 40)]) + \
    R(90, 140, 20, 30, '#3a4664') + R(196, 130, 24, 40, '#3a4664') + R(226, 150, 30, 20, '#3a4664')
L['kingdom-centre'] = ground() + path('M120,180 V70 Q122,30 150,14 Q178,30 180,70 V180Z M134,60 Q136,40 150,30 Q164,40 166,60 V68 H134Z', S, 'fill-rule="evenodd"') + \
    R(134, 72, 32, 4) + R(50, 150, 50, 30, '#3a4664') + R(200, 140, 60, 40, '#3a4664')
L['burj-al-arab'] = water(165) + path('M120,165 V40 L116,20 L126,20 Q200,60 200,165Z', '#f4f1ea', 'stroke="#26304a" stroke-width="3"') + R(116, 20, 8, 145) + \
    line('M126,40 Q170,70 180,165 M126,80 Q160,100 166,165', 1.5, '#9aa3b5') + Cc(196, 110, 10, S) + R(186, 108, 24, 3)
L['al-faisaliah'] = ground() + P([(110, 180), (146, 24), (154, 24), (190, 180)]) + P([(124, 180), (148, 60), (152, 60), (176, 180)], '#cfe8f7') + Cc(150, 50, 12, '#d4a84b') + \
    R(148, 6, 4, 22) + R(40, 156, 50, 24, '#3a4664') + R(212, 150, 54, 30, '#3a4664')
L['kuwait-towers'] = water(170) + R(114, 20, 6, 150) + Cc(117, 72, 24, '#1f6f6a') + Cc(117, 120, 16, '#1f6f6a') + R(166, 50, 6, 120) + Cc(169, 90, 16, '#1f6f6a') + \
    ''.join(Cc(117 + dx, 72 + dy, 2, '#9ad1c9') for dx in (-14, -7, 0, 7, 14) for dy in (-12, -4, 4, 12) if dx * dx + dy * dy < 400) + R(214, 120, 6, 50) + R(206, 120, 22, 4)
L['great-wall'] = path('M0,200 L0,140 Q50,110 90,130 T180,110 T300,120 V200Z', '#5b6b4a') + \
    line('M0,140 Q50,110 90,130 T180,110 T300,120', 12, '#8a7f6b') + ''.join(R(x - 9, y - 22, 18, 22, '#8a7f6b') + ''.join(R(x - 9 + i * 6, y - 26, 4, 4, '#8a7f6b') for i in range(3)) for x, y in [(30, 128), (130, 124), (230, 108)])
L['stonehenge'] = ground(170) + ''.join(R(x, 100, 18, 70) + R(x + 34, 100, 18, 70) + R(x - 4, 90, 60, 12) for x in (40, 180)) + R(120, 120, 16, 50) + R(150, 110, 18, 60) + \
    P([(100, 170), (104, 140), (118, 138), (114, 170)]) + R(250, 130, 16, 40)
L['parthenon'] = ground() + R(40, 160, 220, 20) + R(48, 150, 204, 10) + ''.join(R(x, 82, 10, 68) for x in range(56, 246, 24)) + R(46, 70, 208, 12) + P([(46, 70), (150, 40), (254, 70)]) + \
    P([(150, 40), (190, 52), (196, 70), (230, 70)], '#cfe8f7')
L['arc-de-triomphe'] = ground() + path('M80,180 V40 H220 V180 H178 V120 A28,28 0 0 0 122,120 V180Z') + R(76, 34, 148, 10) + R(80, 60, 140, 3, '#cfe8f7') + \
    path('M94,180 V140 A6,6 0 0 1 106,140 V180Z', '#cfe8f7') + path('M194,180 V140 A6,6 0 0 1 206,140 V180Z', '#cfe8f7')
L['space-needle'] = ground() + path('M110,58 Q150,44 190,58 L176,70 Q150,76 124,70Z') + R(146, 10, 8, 50) + P([(138, 70), (146, 70), (148, 180), (126, 180)]) + P([(154, 70), (162, 70), (174, 180), (152, 180)]) + \
    path('M132,120 Q150,110 168,120 L166,124 Q150,116 134,124Z') + P([(130, 70), (170, 70), (160, 80), (140, 80)])
L['cn-tower'] = water(172) + P([(144, 172), (148, 30), (152, 30), (156, 172)]) + R(149, 4, 2, 30) + path('M132,92 Q150,80 168,92 L166,104 Q150,110 134,104Z') + R(144, 66, 12, 6) + \
    P([(130, 172), (147, 110), (148, 172)]) + P([(170, 172), (153, 110), (152, 172)]) + R(40, 140, 30, 32, '#3a4664') + R(220, 130, 26, 42, '#3a4664') + R(250, 150, 30, 22, '#3a4664')
L['gateway-arch'] = ground() + path('M60,180 Q66,40 150,20 Q234,40 240,180 H226 Q220,58 150,36 Q80,58 74,180Z', '#b8c2cf', 'stroke="#26304a" stroke-width="1.5"') + R(20, 160, 30, 20, '#3a4664') + R(250, 150, 34, 30, '#3a4664')
L['petronas'] = ground() + ''.join(P([(x - 18, 180), (x - 18, 60), (x - 12, 50), (x - 8, 36), (x - 4, 28), (x - 2, 6), (x + 2, 6), (x + 4, 28), (x + 8, 36), (x + 12, 50), (x + 18, 60), (x + 18, 180)]) for x in (110, 190)) + \
    R(128, 94, 44, 6) + P([(140, 100), (146, 100), (128, 130)]) + P([(160, 100), (154, 100), (172, 130)]) + ''.join(R(x - 15, y, 30, 2, '#cfe8f7') for x in (110, 190) for y in range(70, 180, 14))
L['empire-state'] = ground() + R(100, 120, 100, 60) + R(116, 70, 68, 60) + R(130, 40, 40, 40) + R(138, 26, 24, 20) + P([(140, 26), (150, 6), (160, 26)]) + R(149, 0, 2, 10) + \
    ''.join(R(x, 76, 2, 104, '#cfe8f7') for x in range(124, 180, 10)) + R(30, 150, 50, 30, '#3a4664') + R(224, 140, 50, 40, '#3a4664')
L['atomium'] = ground() + ''.join(line(f'M{a[0]},{a[1]} L{b[0]},{b[1]}', 7, '#7a8597') for a, b in [((150, 30), (150, 150)), ((90, 60), (210, 120)), ((210, 60), (90, 120)), ((90, 60), (90, 120)), ((210, 60), (210, 120)), ((90, 60), (210, 60)), ((90, 120), (210, 120)), ((150, 30), (90, 60)), ((150, 30), (210, 60)), ((150, 150), (90, 120)), ((150, 150), (210, 120))]) + \
    ''.join(Cc(x, y, 16, '#aeb7c4') + Cc(x - 5, y - 5, 4, '#ffffff') for x, y in [(150, 30), (90, 60), (210, 60), (150, 90), (90, 120), (210, 120), (150, 150)]) + P([(140, 166), (160, 166), (170, 180), (130, 180)])
L['london-eye'] = water(165) + f'<circle cx="150" cy="90" r="72" fill="none" stroke="{S}" stroke-width="4"/>' + ''.join(line(f'M150,90 L{150 + 72 * math.cos(i * math.pi / 8):.1f},{90 + 72 * math.sin(i * math.pi / 8):.1f}', 1.2) for i in range(16)) + \
    ''.join(f'<ellipse cx="{150 + 76 * math.cos(i * math.pi / 16):.1f}" cy="{90 + 76 * math.sin(i * math.pi / 16):.1f}" rx="4" ry="3" fill="{S}"/>' for i in range(32)) + line('M150,90 L120,165 M150,90 L134,165', 5) + Cc(150, 90, 6)
L['mount-fuji'] = path('M0,200 L0,170 Q60,160 100,120 L135,62 Q150,54 165,62 L200,120 Q240,160 300,170 V200Z', '#4c5d86') + \
    path('M135,62 Q150,54 165,62 L182,90 L172,84 L164,94 L154,84 L146,96 L136,86 L126,92 L118,90Z', '#ffffff') + Cc(240, 50, 18, '#e2574c')
L['jeddah-fountain'] = water(160) + path('M144,160 Q146,60 150,14 Q154,60 156,160Z', '#e8f3fb', 'stroke="#9fc1dd" stroke-width="1.5"') + \
    path('M150,14 Q170,20 180,60 Q170,40 152,30Z', '#e8f3fb', 'stroke="#9fc1dd" stroke-width="1"') + ''.join(Cc(150 + dx, y, 2.5, '#e8f3fb') for dx, y in [(18, 50), (26, 70), (32, 92), (36, 116), (38, 140)]) + R(20, 140, 40, 20, '#3a4664') + R(230, 134, 46, 26, '#3a4664')
L['table-mountain'] = water(172) + path('M0,172 L0,120 L40,90 L70,60 H220 L250,80 L270,70 L300,100 V172Z', '#5c6a7d') + R(70, 56, 150, 6, '#ffffff') + R(0, 150, 300, 22, '#8a9a6a') + \
    ''.join(R(x, 136, 8, 14, '#f4f1ea') for x in range(20, 280, 22))
L['uluru'] = sand(166) + path('M30,166 Q36,120 80,108 Q150,92 230,104 Q272,112 278,166Z', '#c0532f') + ''.join(line(f'M{x},{166} Q{x + 4},{130} {x + 2},{110}', 2, '#9a3e20') for x in range(70, 260, 30))
L['matterhorn'] = path('M0,200 V160 Q70,150 110,110 L140,30 Q150,16 160,40 L190,100 Q230,150 300,150 V200Z', '#55607a') + path('M140,30 Q150,16 160,40 L170,70 L156,62 L146,76 L132,66Z', '#ffffff') + \
    path('M0,200 V176 Q150,150 300,176 V200Z', '#5b7a4a')
L['dubai-frame'] = sand() + path('M110,170 V30 H190 V170Z M124,170 V50 H176 V170Z', '#d4a84b', 'fill-rule="evenodd"') + R(124, 30, 52, 20, '#b8892f') + \
    ''.join(R(x, 36, 6, 8, '#f4e6b8') for x in range(128, 176, 10)) + R(30, 140, 50, 30, '#3a4664') + R(220, 130, 50, 40, '#3a4664')
L['marina-bay-sands'] = water(166) + ''.join(P([(x - 14, 166), (x - 14, 60), (x + 14, 60), (x + 18, 166)]) for x in (90, 150, 210)) + path('M50,54 H264 Q270,54 268,60 H50Z') + R(46, 52, 10, 10) + \
    ''.join(R(x - 10, y, 22, 2, '#cfe8f7') for x in (90, 150, 210) for y in range(70, 166, 12))
L['chichen-itza'] = ground() + ''.join(R(60 + i * 14, 170 - i * 22, 180 - i * 28, 22) for i in range(5)) + R(138, 52, 24, 20) + R(126, 50, 48, 6) + \
    P([(140, 180), (160, 180), (156, 72), (144, 72)], '#3a4664') + ''.join(R(140, y, 20, 2, '#cfe8f7') for y in range(80, 180, 8))
L['louvre-pyramid'] = R(0, 160, 300, 40, '#9aa3b5') + P([(80, 160), (150, 60), (220, 160)], '#8fb6d9') + \
    ''.join(line(f'M{150 - k},{60 + k * 100 / 70:.1f} L{150 + k},{60 + k * 100 / 70:.1f}', 1, '#26304a') for k in range(10, 71, 10)) + \
    ''.join(line(f'M150,60 L{x},160', 1, '#26304a') for x in range(90, 220, 15)) + f'<polygon points="80,160 150,60 220,160" fill="none" stroke="{S}" stroke-width="3"/>' + R(0, 120, 50, 40, '#d9cfb8') + R(250, 120, 50, 40, '#d9cfb8')
L['brandenburg-gate'] = ground() + R(50, 160, 200, 20) + ''.join(R(x, 76, 12, 84) for x in (60, 92, 124, 164, 196, 228)) + R(50, 60, 200, 18) + R(100, 46, 100, 16) + R(136, 32, 28, 16)
L['shard'] = water(170) + P([(110, 170), (148, 14), (152, 14), (190, 170)], '#7d93b0') + line('M150,14 L150,170 M130,90 L170,90', 1.2, '#cfe8f7') + P([(148, 14), (152, 14), (146, 4)], '#7d93b0') + \
    R(30, 140, 50, 30, '#3a4664') + R(222, 130, 50, 40, '#3a4664')
L['taipei-101'] = ground() + ''.join(P([(126, 180 - i * 18), (174, 180 - i * 18), (180, 162 - i * 18), (120, 162 - i * 18)]) for i in range(1)) + R(128, 150, 44, 30) + \
    ''.join(P([(132, 150 - i * 16), (168, 150 - i * 16), (174, 134 - i * 16), (126, 134 - i * 16)]) for i in range(6)) + R(140, 46, 20, 12) + R(146, 30, 8, 18) + R(149, 4, 2, 28)
L['mount-rushmore'] = None  # faces of people: left out on purpose
for k in [k for k, v in L.items() if v is None]: del L[k]

SKY = '<defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cfe8f7"/><stop offset="1" stop-color="#fbe9d0"/></linearGradient></defs>'
for k, body in L.items():
    with open(os.path.join(OUT, f'lm-{k}.svg'), 'w') as f:
        f.write(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200" width="600" height="400">{SKY}<rect width="300" height="200" fill="url(#sky)"/>{body}</svg>')
print(len(L), 'landmarks')
